/*!
 * js/sky.js - 오픈월드용 3D 하늘 (낮/밤, 해, 달, 별)
 *
 * - 하루 20분 = 낮 10분 + 밤 10분 (접속자 모두 같은 시각. 기준: 기기 시계의 20분 주기)
 * - 해/달/별은 항상 동쪽(+x)에서 떠서 남쪽 하늘을 지나 서쪽(-x)으로 져요. 북쪽 = -z.
 * - 게임 카메라가 실제로 보는 방향을 그대로 쓰기 때문에, 시점을 어떻게 돌려도 방향이 맞아요.
 * - main.js 를 고치지 않아요. index.html 에서 main.js 보다 먼저 불러오면 스스로 장면에 붙어요.
 * - 땅/물 조명도 같이 바뀌어요 (밤엔 어둡고 푸르게). 방 안(땅 밑 방)에서는 항상 낮 조명.
 *
 * 날씨/바람 (구름이 여기에 따라 변해요. 값을 바꾸면 몇 초에 걸쳐 부드럽게 바뀌어요):
 *   Sky.setWeather({ cloudCover: 0~1(구름 양), storm: 0~1(먹구름/폭풍 정도), windDir: 도(구름이 가는 방향, 북0 동90 남180 서270), windSpeed: 0~(바람 세기, 보통 1) })
 *   또는 Sky.weather.cloudCover = 0.8 처럼 직접 바꿔도 돼요.
 * 별똥별: 밤에 맑을 때 초당 확률 shootingStarChance(기본 0.01 = 100초에 한 번꼴). Sky.setShootingStarChance(0.05), Sky.shootStar() 로 바로 한 번 쏠 수도 있어요.
 *
 * 테스트용 주소 옵션:  ?skyspeed=60 (60배속)   ?skytime=0 (0=해뜸, 300=정오, 600=해짐, 900=한밤)
 *   ?skycloud=0.8 (구름 양)  ?skystorm=0.5  ?skywind=3  ?skywinddir=90  ?skymeteor=0.5 (별똥별 확률)
 * 설정을 바꾸고 싶으면 이 파일을 불러오기 전에 window.SKY_OPTIONS = { latitude: 37, ... } 를 지정하세요.
 */
import * as THREE from 'three';

const MOON_SRC = "data:image/png;base64,";

const Q = typeof location !== 'undefined' ? location.search : '';
const OPT = Object.assign({
  dayLength: 1200,    // 하루(초)
  speed: 1,           // 1 = 실제 속도
  latitude: 37,       // 북위(도): 별이 도는 모양과 해의 높이를 정해요
  starCount: 3600,
  sunRadius: 0.038,   // 해 알맹이 크기(라디안). 실제보다 일부러 크게
  moonRadius: 0.06,
  shootingStarChance: 0.01,  // 별똥별: 초당 확률 (0.01 = 1초에 100분의 1)
  clouds: true,       // false 면 구름을 그리지 않아요 (느린 기기용)
  lights: true,       // false 면 땅/물 조명은 건드리지 않아요
  weather: {}         // 시작 날씨. 예: { cloudCover: 0.5 }
}, (typeof window !== 'undefined' && window.SKY_OPTIONS) || {});
{ const m = /[?&]skyspeed=([\d.]+)/.exec(Q); if (m) OPT.speed = parseFloat(m[1]); }
const qnum = (k) => { const m = new RegExp('[?&]' + k + '=(-?[\\d.]+)').exec(Q); return m ? parseFloat(m[1]) : null; };
{ const m = qnum('skymeteor'); if (m !== null) OPT.shootingStarChance = m; }
// 날씨 값: 게임이 바꾸는 목표값(WX_T)과 화면에 보이는 현재값(WX). 현재값이 목표값으로 천천히 따라가요.
const WX_T = Object.assign({ cloudCover: 0.35, storm: 0, windDir: 90, windSpeed: 1 }, OPT.weather);
{ const a = qnum('skycloud'), b = qnum('skystorm'), c = qnum('skywind'), d = qnum('skywinddir');
  if (a !== null) WX_T.cloudCover = a; if (b !== null) WX_T.storm = b; if (c !== null) WX_T.windSpeed = c; if (d !== null) WX_T.windDir = d; }
const WX = { cloudCover: WX_T.cloudCover, storm: WX_T.storm, wx: 0, wz: 0, ox: 0, oz: 0 };
{ const a = WX_T.windDir * Math.PI / 180; WX.wx = Math.sin(a) * WX_T.windSpeed; WX.wz = -Math.cos(a) * WX_T.windSpeed; }
let offset = 0;
{ const m = /[?&]skytime=([\d.]+)/.exec(Q); if (m) offset = parseFloat(m[1]) - (Date.now() / 1000) * OPT.speed; }

// ---------------- 셰이더 (GLSL 주석은 영어로) ----------------
const DOME_VS = `
varying vec3 vDir;
void main() {
  vDir = position;
  mat4 vm = viewMatrix;
  vm[3] = vec4(0.0, 0.0, 0.0, 1.0);
  vec4 p = projectionMatrix * vm * vec4(position, 1.0);
  gl_Position = p.xyww;
}`;

const DOME_FS = `
uniform vec3 uTop;
uniform vec3 uHor;
uniform vec3 uSunDir;
uniform vec3 uMoonDir;
uniform vec3 uSunCol;
uniform float uSunK;
uniform float uSunVis;
uniform float uMoonVis;
uniform float uSunR;
uniform float uMoonR;
uniform float uMoonReady;
uniform sampler2D uMoonTex;
uniform float uCover;
uniform float uStorm;
uniform vec2 uWindOff;
uniform vec2 uWindDir;
uniform float uCT;
uniform vec3 uLightDir;
uniform vec3 uLightCol;
uniform float uLightAmt;
uniform vec3 uMetA[3];
uniform vec3 uMetB[3];
uniform vec3 uMetP;
uniform float uMetVis;
varying vec3 vDir;

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm4(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p);
    p = p * 2.03 + vec2(17.1, 9.7);
    a *= 0.5;
  }
  return v;
}
float cloudDensity(vec2 uv, float th) {
  vec2 w = vec2(vnoise(uv * 0.7 + uCT * 0.011), vnoise(uv * 0.7 + 31.7 - uCT * 0.009)) - 0.5;
  float f = fbm4(uv + w * 0.8);
  return smoothstep(th, th + 0.14, f);
}

void main() {
  vec3 d = normalize(vDir);
  float h = d.y;
  vec3 col = mix(uHor, uTop, pow(clamp(h, 0.0, 1.0), 0.55));

  // warm glow along the horizon on the sun side (sunrise / sunset)
  vec3 sh = normalize(vec3(uSunDir.x, 0.0, uSunDir.z) + vec3(0.0001, 0.0, 0.0));
  vec3 dh = normalize(vec3(d.x, 0.0, d.z) + vec3(0.0001, 0.0, 0.0));
  float az = max(dot(dh, sh), 0.0);
  float band = exp(-pow(max(h, 0.0) / 0.20, 2.0));
  col += uSunCol * (pow(az, 3.0) * band * 0.30 * uSunK * uSunVis);

  // sun: photographic look - white-hot core, long soft bloom, faint diffraction streaks
  float s = dot(d, uSunDir);
  float ang = acos(clamp(s, -1.0, 1.0));
  float r = uSunR;
  float x = ang / r;
  float front = step(0.0, s);
  float dim = 1.0 - 0.30 * uSunK;
  vec3 tint = mix(vec3(1.0, 0.97, 0.92), uSunCol, uSunK * 0.8);
  float bloom = 0.62 / (1.0 + pow(x * 0.50, 2.2)) + 0.15 * exp(-x / 16.0);
  vec3 sr = normalize(cross(uSunDir, vec3(0.0, 1.0, 0.0)) + vec3(0.00001, 0.0, 0.0));
  vec3 su = cross(sr, uSunDir);
  vec3 sdd = d - uSunDir * s;
  float th = atan(dot(sdd, su), dot(sdd, sr));
  float rays = pow(abs(cos(th * 3.0 + 0.4)), 26.0) + 0.6 * pow(abs(cos(th * 5.0 + 1.1)), 34.0);
  float sunLight = (bloom + rays * 0.028 * exp(-x / 9.0)) * dim * uSunVis * front;
  col = vec3(1.0) - (vec3(1.0) - col) * exp(-tint * sunLight * 1.6);
  float disc = (1.0 - smoothstep(r * 0.96, r * 1.04, ang)) * front;
  vec3 lowCol = mix(vec3(1.0, 0.86, 0.55), vec3(1.0, 0.66, 0.34), smoothstep(0.2, 1.0, x));
  vec3 dcol = mix(vec3(1.0, 0.995, 0.97), lowCol, uSunK * 0.95) * (1.0 - 0.14 * uSunK * min(x * x, 1.0));
  col = mix(col, dcol, disc * uSunVis);

  // moon (transparent PNG texture on a small patch of the sky)
  float ms = dot(d, uMoonDir);
  float mang = acos(clamp(ms, -1.0, 1.0));
  col += vec3(0.62, 0.72, 1.0) * exp(-mang / (uMoonR * 3.0)) * 0.16 * uMoonVis * step(0.0, ms);
  vec3 mr = normalize(cross(uMoonDir, vec3(0.0, 1.0, 0.0)) + vec3(0.00001, 0.0, 0.0));
  vec3 mu = cross(mr, uMoonDir);
  vec3 dd = d - uMoonDir * ms;
  vec2 q = vec2(dot(dd, mr), dot(dd, mu)) / uMoonR;
  vec4 mt = texture2D(uMoonTex, clamp(q * 0.5 + 0.5, 0.0, 1.0));
  float inside = step(abs(q.x), 1.0) * step(abs(q.y), 1.0) * step(0.0, ms);
  col = mix(col, mt.rgb, mt.a * inside * uMoonVis * uMoonReady);

  // below the horizon the sun/moon sink softly into the haze (no hard cut at the horizon line)
  col = mix(col, uHor, 1.0 - smoothstep(-0.07, 0.0, h));

  // shooting stars (up to 3 at once)
  for (int i = 0; i < 3; i++) {
    float p = uMetP.z;
    if (i == 0) p = uMetP.x;
    if (i == 1) p = uMetP.y;
    if (p >= 0.0) {
      vec3 H = normalize(mix(uMetA[i], uMetB[i], clamp(p, 0.0, 1.0)));
      vec3 T = normalize(mix(uMetA[i], uMetB[i], clamp(p - 0.35, 0.0, 1.0)));
      vec3 hd = H - T;
      float u = clamp(dot(d - T, hd) / (dot(hd, hd) + 0.000001), 0.0, 1.0);
      float dist = length(d - (T + hd * u));
      float w = 0.0022 * (0.4 + 0.6 * u);
      float fade = 1.0 - smoothstep(1.0, 1.35, p);
      float b = exp(-pow(dist / w, 2.0)) * pow(u, 1.4) + 0.5 * exp(-length(d - H) / 0.006);
      col += vec3(1.0, 0.96, 0.88) * b * fade * uMetVis * 1.4;
    }
  }

  // clouds (weather + wind driven)
  if (h > 0.0 && uCover >= 0.0) {
    float thr = mix(0.70, 0.30, uCover) - 0.06 * uStorm;
    float hf = smoothstep(0.0, 0.16, h);
    vec3 amb = mix(uHor, uTop, 0.55) * 0.92 + 0.05;
    float lum = dot(amb, vec3(0.30, 0.59, 0.11));
    amb = mix(amb, vec3(lum), 0.45);

    // thin high clouds, stretched along the wind
    vec2 uh = d.xz / (h * 0.9 + 0.4) * 0.5 + uWindOff * 0.6;
    vec2 wd = uWindDir;
    vec2 pp = vec2(dot(uh, wd) * 0.35, dot(uh, vec2(-wd.y, wd.x)) * 2.2);
    float ci = smoothstep(0.52, 0.86, fbm4(pp)) * 0.32 * (1.0 - uCover * 0.5) * (1.0 - uStorm) * hf;
    vec3 cic = amb + uLightCol * uLightAmt * 0.9;
    col = mix(col, clamp(cic, 0.0, 1.0), ci);

    // low clouds with simple self shadowing and silver lining
    vec2 uv = d.xz / (h * 0.85 + 0.14) * 1.1 + uWindOff;
    float dens = cloudDensity(uv, thr);
    vec2 ld = normalize(uLightDir.xz + vec2(0.0001, 0.0));
    float dens2 = cloudDensity(uv + ld * 0.05, thr);
    float lit = mix(1.0, 0.30, clamp(dens2 * 1.2 - dens * 0.2, 0.0, 1.0));
    vec3 base = amb * (1.0 - 0.45 * uStorm);
    vec3 cc = base + uLightCol * uLightAmt * lit * (1.0 - 0.6 * uStorm);
    float silver = pow(max(dot(d, uLightDir), 0.0), 8.0) * (1.0 - dens * 0.55) * uLightAmt;
    cc += uLightCol * silver * 0.5;
    float ca = dens * hf * mix(0.92, 1.0, uStorm);
    col = mix(col, clamp(cc, 0.0, 1.0), ca);
  }

  gl_FragColor = vec4(col, 1.0);
}`;

const STAR_VS = `
attribute vec4 aInfo;
uniform float uH;
uniform float uLat;
uniform float uAlpha;
uniform float uTime;
uniform float uPx;
varying float vA;
varying vec3 vC;
void main() {
  float ra = position.x;
  float dec = position.y;
  float H = uH - ra;
  float cH = cos(H);
  float sd = sin(dec);
  float cd = cos(dec);
  float sinAlt = sin(uLat) * sd + cos(uLat) * cd * cH;
  float cosAlt = sqrt(max(0.0, 1.0 - sinAlt * sinAlt));
  float az = atan(-cd * sin(H), sd * cos(uLat) - cd * sin(uLat) * cH);
  vec3 dir = vec3(sin(az) * cosAlt, sinAlt, -cos(az) * cosAlt);
  vA = uAlpha * aInfo.x * smoothstep(0.0, 0.12, sinAlt) * (0.75 + 0.25 * sin(uTime * 1.4 + aInfo.z));
  vC = mix(vec3(0.80, 0.88, 1.0), vec3(1.0, 0.92, 0.78), aInfo.w);
  mat4 vm = viewMatrix;
  vm[3] = vec4(0.0, 0.0, 0.0, 1.0);
  vec4 p = projectionMatrix * vm * vec4(dir * 10.0, 1.0);
  gl_Position = p.xyww;
  gl_PointSize = aInfo.y * uPx;
}`;

const STAR_FS = `
varying float vA;
varying vec3 vC;
void main() {
  float d = length(gl_PointCoord - vec2(0.5));
  float a = 1.0 - smoothstep(0.1, 0.5, d);
  gl_FragColor = vec4(vC, a * vA);
}`;

// ---------------- 계산 (THREE 없이도 동작) ----------------
const rad = (d) => d * Math.PI / 180;
const deg = (r) => r * 180 / Math.PI;
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const ss = (x) => { x = clamp(x, 0, 1); return x * x * (3 - 2 * x); };
const lerp = (a, b, k) => a + (b - a) * k;

const STOPS = [
  [-1,    '#04060f', '#0a1030'],
  [-0.55, '#060a1e', '#101840'],
  [-0.3,  '#1c2352', '#5a3a68'],
  [-0.12, '#35306a', '#b8576a'],
  [0.02,  '#46549c', '#f08f58'],
  [0.22,  '#4a86d2', '#cfe3f2'],
  [0.6,   '#3b82d6', '#a8d8f5'],
  [1,     '#3b82d6', '#a8d8f5']
];
const hex3 = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) / 255);
function skyColors(alt) {
  for (let i = 0; i < STOPS.length - 1; i++) {
    const s = STOPS[i], e = STOPS[i + 1];
    if (alt <= e[0]) {
      let k = (alt - s[0]) / (e[0] - s[0]); k = k * k * (3 - 2 * k);
      const mix = (a, b) => hex3(a).map((v, j) => lerp(v, hex3(b)[j], k));
      return { top: mix(s[1], e[1]), hor: mix(s[2], e[2]) };
    }
  }
  const l = STOPS[STOPS.length - 1];
  return { top: hex3(l[1]), hor: hex3(l[2]) };
}

// 시간각 H, 적위 dec, 위도 lat(라디안) -> 고도/방위(도). 방위: 북=0, 동=90, 남=180, 서=270
function altaz(H, dec, lat) {
  const cH = Math.cos(H), sd = Math.sin(dec), cd = Math.cos(dec);
  const sin = Math.sin(lat) * sd + Math.cos(lat) * cd * cH;
  const az = Math.atan2(-cd * Math.sin(H), sd * Math.cos(lat) - cd * Math.sin(lat) * cH);
  return { sin, alt: deg(Math.asin(clamp(sin, -1, 1))), az: (deg(az) + 360) % 360 };
}
// 게임 세계 방향 벡터: 북 = -z, 동 = +x, 위 = +y
function dirOf(p) {
  const a = rad(p.alt), z = rad(p.az);
  return [Math.sin(z) * Math.cos(a), Math.sin(a), -Math.cos(z) * Math.cos(a)];
}

function computeState(nowSec) {
  const L = OPT.dayLength, half = L / 2;
  const t = (((nowSec * OPT.speed + offset) % L) + L) % L;
  const H = 2 * Math.PI * (t - L / 4) / L;          // t=0 해 뜸(동), L/4 정오(남), L/2 해 짐(서)
  const lat = rad(OPT.latitude);
  const sun = altaz(H, 0, lat), moon = altaz(H + Math.PI, 0, lat);
  const x = clamp((0.2 - sun.sin) / 0.7, 0, 1);
  return {
    time: t, isDay: t < half, isNight: t >= half,
    secondsLeft: Math.ceil(half - (t % half)),
    altitude: sun.sin, hourAngle: H, sun, moon,
    darkness: x * x * (3 - 2 * x)                    // 0 = 낮, 1 = 한밤
  };
}

// ---- 날씨: 목표값(WX_T)을 향해 현재값(WX)이 부드럽게 따라가요 ----
function stepWeather(dt) {
  if (!(dt > 0)) return;
  const kc = 1 - Math.exp(-dt / 6), kw = 1 - Math.exp(-dt / 3);
  WX.cloudCover += (clamp(WX_T.cloudCover, 0, 1) - WX.cloudCover) * kc;
  WX.storm += (clamp(WX_T.storm, 0, 1) - WX.storm) * kc;
  const a = rad(WX_T.windDir), sp = Math.max(0, WX_T.windSpeed);
  WX.wx += (Math.sin(a) * sp - WX.wx) * kw;
  WX.wz += (-Math.cos(a) * sp - WX.wz) * kw;
  // 구름 무늬가 바람 방향으로 흘러가도록 (무늬 좌표는 반대로 이동)
  WX.ox = (WX.ox - WX.wx * dt * 0.004) % 200;
  WX.oz = (WX.oz - WX.wz * dt * 0.004) % 200;
}

// ---- 별똥별 ----
const MET = [0, 1, 2].map(() => ({ age: -1, A: [0, 1, 0], B: [0, 1, 0] }));
const v3 = {
  cross: (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]],
  norm: (a) => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; }
};
// fwd = 지금 카메라가 보는 방향. 그 근처 하늘에서 떨어지게 해서 실제로 눈에 띄게 함
function spawnMeteor(fwd) {
  const m = MET.find((x) => x.age < 0);
  if (!m) return;
  const az0 = Math.atan2(fwd[0], -fwd[2]), alt0 = Math.asin(clamp(fwd[1], -1, 1));
  const az = az0 + (Math.random() - 0.5) * 1.2;
  const alt = clamp(alt0 + (Math.random() - 0.2) * 0.5, 0.3, 1.25);
  const P = [Math.sin(az) * Math.cos(alt), Math.sin(alt), -Math.cos(az) * Math.cos(alt)];
  const e = v3.norm(v3.cross([0, 1, 0], P)), n = v3.cross(P, e);
  const phi = Math.random() * Math.PI * 2, len = 0.25 + Math.random() * 0.3;
  let T = [e[0] * Math.cos(phi) + n[0] * Math.sin(phi), e[1] * Math.cos(phi) + n[1] * Math.sin(phi), e[2] * Math.cos(phi) + n[2] * Math.sin(phi)];
  let B = v3.norm([P[0] + T[0] * len, P[1] + T[1] * len, P[2] + T[2] * len]);
  if (B[1] < 0.15) { T = [-T[0], -T[1], -T[2]]; B = v3.norm([P[0] + T[0] * len, P[1] + T[1] * len, P[2] + T[2] * len]); }
  m.A = P; m.B = B; m.age = 0;
}
// vis = 별이 보이는 정도(밤 + 맑음). 확률은 "초당" 이라서 dt 를 곱해요
function stepMeteors(dt, fwd, vis) {
  for (const m of MET) if (m.age >= 0) { m.age += dt; if (m.age * 1.8 > 1.5) m.age = -1; }
  if (fwd && vis > 0.3 && Math.random() < OPT.shootingStarChance * dt) spawnMeteor(fwd);
}

// 하늘에 필요한 모든 값을 한 번에 계산 (THREE 없이도 동작 -> 테스트/미리보기에서 그대로 사용)
function buildUniforms(st) {
  const c = skyColors(st.altitude);
  const k = 1 - ss(Math.max(0, st.sun.alt) / 22);   // 0 = 높이 떠 있음, 1 = 지평선 근처
  const cover = WX.cloudCover, storm = WX.storm;
  const o = clamp(cover * 0.5 + storm * 0.85, 0, 1);  // 하늘이 회색으로 덮이는 정도
  const grey = (col, f) => { const l = 0.3 * col[0] + 0.59 * col[1] + 0.11 * col[2]; return col.map((v) => lerp(v, l * f, o * 0.75)); };
  const top = grey(c.top, 0.80 - 0.25 * storm), hor = grey(c.hor, 0.95 - 0.25 * storm);
  const sunDir = dirOf(st.sun), moonDir = dirOf(st.moon);
  const sunCol = [1, lerp(0.96, 0.5, k), lerp(0.86, 0.22, k)];
  const starVis = clamp(1 - cover * 0.9 - storm, 0, 1) * ss((-st.altitude - 0.02) / 0.3);

  // 구름을 비추는 빛: 해(해 진 직후까지) 또는 달
  const sunAmt = ss((st.sun.sin + 0.10) / 0.28), moonAmt = 0.14 * ss(st.moon.sin / 0.25) * (1 - sunAmt);
  const useSun = sunAmt >= moonAmt;
  const wl = Math.hypot(WX.wx, WX.wz);
  const wd = wl > 0.01 ? [WX.wx / wl, WX.wz / wl] : [Math.sin(rad(WX_T.windDir)), -Math.cos(rad(WX_T.windDir))];
  const metP = MET.map((m) => (m.age >= 0 ? m.age * 1.8 : -1));

  return {
    dome: {
      uTop: top, uHor: hor, uSunDir: sunDir, uMoonDir: moonDir, uSunCol: sunCol, uSunK: k,
      uSunVis: ss((st.sun.alt + 12) / 6) * (1 - 0.6 * storm) * (1 - 0.25 * cover),
      uMoonVis: ss((st.moon.alt + 12) / 6) * (1 - 0.5 * storm),
      uSunR: OPT.sunRadius * (1 + 0.4 * k),
      uMoonR: OPT.moonRadius * (1 + 0.25 * (1 - Math.min(1, Math.max(0, st.moon.alt) / 40))),
      uCover: OPT.clouds ? cover : -1, uStorm: storm,
      uWindOff: [WX.ox, WX.oz], uWindDir: wd, uCT: performance.now() / 1000 % 5000,
      uLightDir: useSun ? sunDir : moonDir,
      uLightCol: useSun ? [1, lerp(0.97, 0.62, k), lerp(0.9, 0.42, k)] : [0.62, 0.72, 1.0],
      uLightAmt: Math.max(sunAmt, moonAmt) * (1 - 0.25 * storm),
      uMetA: [].concat(MET[0].A, MET[1].A, MET[2].A), uMetB: [].concat(MET[0].B, MET[1].B, MET[2].B),
      uMetP: metP, uMetVis: starVis
    },
    star: { uH: st.hourAngle, uAlpha: starVis },
    k, hor, sunDir, moonDir,
    shade: clamp(1 - 0.45 * cover - 0.35 * storm, 0.25, 1)   // 날씨에 따른 땅 밝기 배율
  };
}

function rng(a) {
  return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
}
function makeStarData(n) {
  const r = rng(20240607), pos = new Float32Array(n * 3), info = new Float32Array(n * 4);
  const nBand = Math.floor(n * 0.28), tilt = 1.05;
  for (let i = 0; i < n; i++) {
    const band = i < nBand;               // 일부는 은하수처럼 한 줄로 촘촘하게 (어둡게)
    let ra, dec;
    if (band) {
      const ph = r() * Math.PI * 2, b = (r() + r() + r() - 1.5) * 0.30;
      const x = Math.cos(b) * Math.cos(ph), y = Math.cos(b) * Math.sin(ph), z = Math.sin(b);
      const y2 = y * Math.cos(tilt) - z * Math.sin(tilt), z2 = y * Math.sin(tilt) + z * Math.cos(tilt);
      ra = Math.atan2(y2, x); dec = Math.asin(clamp(z2, -1, 1));
    } else {
      ra = r() * Math.PI * 2; dec = Math.asin(2 * r() - 1);
    }
    const q = Math.pow(r(), band ? 3.2 : 2.6);
    pos[i * 3] = ra; pos[i * 3 + 1] = dec;
    info[i * 4] = band ? 0.18 + 0.40 * q : 0.28 + 0.72 * q;   // 밝기
    info[i * 4 + 1] = band ? 1.0 + 1.2 * q : 1.1 + 2.4 * q;   // 크기(px)
    info[i * 4 + 2] = r() * 6.28;                              // 반짝임 위상
    info[i * 4 + 3] = r() < 0.18 ? 1 : 0;                      // 따뜻한 색
  }
  return { pos, info };
}

// ---------------- 장면에 붙이기 ----------------
const moonReady = { value: 0 };
const moonTex = new THREE.TextureLoader().load(MOON_SRC, () => { moonReady.value = 1; });

function install(scene) {
  const hemi = scene.children.find((o) => o.isHemisphereLight);
  const sunL = scene.children.find((o) => o.isDirectionalLight);

  const V3 = () => new THREE.Vector3();
  const uni = {
    uTop: { value: V3() }, uHor: { value: V3() },
    uSunDir: { value: new THREE.Vector3(0, 1, 0) }, uMoonDir: { value: new THREE.Vector3(0, -1, 0) },
    uSunCol: { value: new THREE.Vector3(1, 1, 1) },
    uSunK: { value: 0 }, uSunVis: { value: 1 }, uMoonVis: { value: 0 },
    uSunR: { value: OPT.sunRadius }, uMoonR: { value: OPT.moonRadius },
    uMoonReady: moonReady, uMoonTex: { value: moonTex },
    uCover: { value: 0 }, uStorm: { value: 0 }, uWindOff: { value: new THREE.Vector2() }, uWindDir: { value: new THREE.Vector2(1, 0) },
    uCT: { value: 0 }, uLightDir: { value: new THREE.Vector3(0, 1, 0) }, uLightCol: { value: new THREE.Vector3(1, 1, 1) }, uLightAmt: { value: 1 },
    uMetA: { value: [V3(), V3(), V3()] }, uMetB: { value: [V3(), V3(), V3()] }, uMetP: { value: new THREE.Vector3(-1, -1, -1) }, uMetVis: { value: 0 }
  };
  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(10, 48, 24),
    new THREE.ShaderMaterial({
      uniforms: uni, vertexShader: DOME_VS, fragmentShader: DOME_FS,
      side: THREE.DoubleSide, depthWrite: false, depthFunc: THREE.LessEqualDepth
    })
  );
  dome.frustumCulled = false; dome.renderOrder = -1000;
  scene.add(dome);

  const sd = makeStarData(OPT.starCount);
  const sg = new THREE.BufferGeometry();
  sg.setAttribute('position', new THREE.BufferAttribute(sd.pos, 3));
  sg.setAttribute('aInfo', new THREE.BufferAttribute(sd.info, 4));
  const su = {
    uH: { value: 0 }, uLat: { value: rad(OPT.latitude) }, uAlpha: { value: 0 },
    uTime: { value: 0 }, uPx: { value: 1 }
  };
  const stars = new THREE.Points(sg, new THREE.ShaderMaterial({
    uniforms: su, vertexShader: STAR_VS, fragmentShader: STAR_FS,
    transparent: true, depthWrite: false, depthTest: true, depthFunc: THREE.LessEqualDepth,
    blending: THREE.AdditiveBlending
  }));
  stars.frustumCulled = false; stars.renderOrder = -999;
  scene.add(stars);

  // 원래(낮) 값 기억 -> 방 안에서는 이 값으로 되돌림
  const day = {
    hi: hemi ? hemi.intensity : 1, hc: hemi ? hemi.color.clone() : null, hg: hemi ? hemi.groundColor.clone() : null,
    si: sunL ? sunL.intensity : 1, sc: sunL ? sunL.color.clone() : null, sp: sunL ? sunL.position.clone() : null,
    bg: scene.background && scene.background.isColor ? scene.background.clone() : null,
    fog: scene.fog ? scene.fog.color.clone() : null
  };
  const nightHemi = new THREE.Color(0x7f90c8), nightGround = new THREE.Color(0x1a2036);
  const warmSun = new THREE.Color(0xff9a55), moonCol = new THREE.Color(0x9fb4ff);
  const fwdV = new THREE.Vector3();
  let lastMs = performance.now();

  function restoreDay() {
    if (OPT.lights && hemi) { hemi.intensity = day.hi; hemi.color.copy(day.hc); hemi.groundColor.copy(day.hg); }
    if (OPT.lights && sunL) { sunL.intensity = day.si; sunL.color.copy(day.sc); sunL.position.copy(day.sp); }
    if (day.bg) scene.background.copy(day.bg);
    if (day.fog) scene.fog.color.copy(day.fog);
  }

  function before(renderer, camera) {
    const main = renderer.getRenderTarget() === null;
    // 방 안 화면은 main.js 가 땅/하늘을 숨기고 그려요 -> 이때는 낮 조명으로
    if (main && !dome.visible) { restoreDay(); return; }

    const nowMs = performance.now(), dt = Math.min(0.1, (nowMs - lastMs) / 1000);
    lastMs = nowMs;
    stepWeather(dt);

    const st = computeState(Date.now() / 1000);
    // 별똥별은 메인 화면에서만, 카메라가 보는 방향 근처에 생겨요
    if (main && dt > 0) {
      camera.getWorldDirection(fwdV);
      stepMeteors(dt, [fwdV.x, fwdV.y, fwdV.z], ss((-st.altitude - 0.02) / 0.3) * clamp(1 - WX.cloudCover * 0.9 - WX.storm, 0, 1));
    }
    const U = buildUniforms(st), d = U.dome;

    uni.uTop.value.set(...d.uTop); uni.uHor.value.set(...d.uHor);
    uni.uSunDir.value.set(...d.uSunDir); uni.uMoonDir.value.set(...d.uMoonDir);
    uni.uSunCol.value.set(...d.uSunCol);
    uni.uSunK.value = d.uSunK; uni.uSunVis.value = d.uSunVis; uni.uMoonVis.value = d.uMoonVis;
    uni.uSunR.value = d.uSunR; uni.uMoonR.value = d.uMoonR;
    uni.uCover.value = d.uCover; uni.uStorm.value = d.uStorm; uni.uCT.value = d.uCT;
    uni.uWindOff.value.set(...d.uWindOff); uni.uWindDir.value.set(...d.uWindDir);
    uni.uLightDir.value.set(...d.uLightDir); uni.uLightCol.value.set(...d.uLightCol); uni.uLightAmt.value = d.uLightAmt;
    for (let i = 0; i < 3; i++) {
      uni.uMetA.value[i].set(d.uMetA[i * 3], d.uMetA[i * 3 + 1], d.uMetA[i * 3 + 2]);
      uni.uMetB.value[i].set(d.uMetB[i * 3], d.uMetB[i * 3 + 1], d.uMetB[i * 3 + 2]);
    }
    uni.uMetP.value.set(...d.uMetP); uni.uMetVis.value = d.uMetVis;
    su.uH.value = U.star.uH; su.uAlpha.value = U.star.uAlpha;
    su.uTime.value = nowMs / 1000; su.uPx.value = renderer.getPixelRatio();
    stars.visible = U.star.uAlpha > 0.01;

    // 먼 땅이 하늘 지평선 색으로 자연스럽게 사라지게
    if (scene.fog) scene.fog.color.setRGB(U.hor[0], U.hor[1], U.hor[2], THREE.SRGBColorSpace);
    if (scene.background && scene.background.isColor) scene.background.setRGB(U.hor[0], U.hor[1], U.hor[2], THREE.SRGBColorSpace);

    if (!OPT.lights) return;
    const dk = st.darkness;
    if (hemi) {
      hemi.intensity = lerp(day.hi, 0.32, dk) * lerp(1, U.shade, 0.6);
      hemi.color.lerpColors(day.hc, nightHemi, dk);
      hemi.groundColor.lerpColors(day.hg, nightGround, dk);
    }
    if (sunL) {
      if (st.sun.sin > -0.05) {            // 해가 떠 있을 때: 해가 빛을 줌 (질 때는 주황빛, 흐리면 약하게)
        sunL.intensity = day.si * ss((st.sun.sin + 0.03) / 0.2) * U.shade;
        sunL.color.lerpColors(day.sc, warmSun, U.k);
        sunL.position.set(U.sunDir[0] * 100, U.sunDir[1] * 100, U.sunDir[2] * 100);
      } else {                             // 밤: 달빛
        sunL.intensity = 0.32 * ss(st.moon.sin / 0.25) * U.shade;
        sunL.color.copy(moonCol);
        sunL.position.set(U.moonDir[0] * 100, U.moonDir[1] * 100, U.moonDir[2] * 100);
      }
    }
  }
  return { scene, before };
}

// main.js 가 renderer.render(scene, camera)를 부를 때마다 하늘을 갱신 (main.js 수정 불필요)
if (THREE.WebGLRenderer && THREE.WebGLRenderer.prototype) {
  const proto = THREE.WebGLRenderer.prototype;
  const origRender = proto.render;
  let sky = null, failed = false;
  proto.render = function (scene, camera) {
    if (!failed && scene && scene.isScene) {
      try {
        if (!sky) sky = install(scene);
        if (sky.scene === scene) sky.before(this, camera);
      } catch (e) {
        failed = true;
        console.error('[sky] 하늘을 붙이지 못했어요:', e);
      }
    }
    return origRender.call(this, scene, camera);
  };
}

if (typeof window !== 'undefined') {
  window.Sky = {
    getState: () => computeState(Date.now() / 1000),
    setTime: (sec) => { offset = sec - (Date.now() / 1000) * OPT.speed; },   // 0=해뜸 300=정오 600=해짐 900=한밤
    setSpeed: (v) => { const t = computeState(Date.now() / 1000).time; OPT.speed = v; offset = t - (Date.now() / 1000) * v; },
    // 날씨/바람: 목표값을 바꾸면 현재 하늘이 몇 초에 걸쳐 부드럽게 따라가요. instant 로 즉시 바꿀 수도 있어요.
    weather: WX_T,
    setWeather: (w, opts) => {
      Object.assign(WX_T, w || {});
      if (opts && opts.instant) {
        WX.cloudCover = clamp(WX_T.cloudCover, 0, 1); WX.storm = clamp(WX_T.storm, 0, 1);
        const a = rad(WX_T.windDir); WX.wx = Math.sin(a) * WX_T.windSpeed; WX.wz = -Math.cos(a) * WX_T.windSpeed;
      }
    },
    getWeather: () => ({ ...WX_T }),
    setShootingStarChance: (v) => { OPT.shootingStarChance = v; },   // 초당 확률 (0.01 = 100초에 한 번)
    shootStar: () => { const f = [0, 0.5, -0.85]; spawnMeteor(f); }  // 테스트용: 지금 바로 한 번 (카메라 방향은 무시)
  };
}

export const __sky = { computeState, buildUniforms, stepWeather, stepMeteors, spawnMeteor, makeStarData, DOME_VS, DOME_FS, STAR_VS, STAR_FS, OPT, WX, WX_T, MET };
